def select_words(s, n):
    def is_consonant(c):
        return (c.isalpha() and c.lower() not in 'aeiou')

    def count_consonants(word):
        return sum(1 for c in word if is_consonant(c))

    if not s:
        return []

    words = s.split()
    result = [word for word in words if count_consonants(word) == n]

    return result

