// Helper function to count consonants in a word
function CountConsonants(word: string): int
    reads {}
    requires forall i :: 0 <= i < word.Length ==> ('a' <= word[i] && word[i] <= 'z') || ('A' <= word[i] && word[i] <= 'Z')
    ensures 0 <= CountConsonants(word) <= word.Length // The count of consonants is non-negative and cannot exceed the length of the word.
    decreases word.Length
{
    var count := 0;
    var i := 0;
    while i < word.Length
        invariant 0 <= i <= word.Length // i is within bounds
        invariant count == CountConsonants(word[0..i]) // Count of consonants up to current index
    {
        if IsConsonant(word[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to check if a character is a consonant
function IsConsonant(c: char): bool
    reads {}
{
    return ('a' <= c && c <= 'z' && !(c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')) ||
           ('A' <= c && c <= 'Z' && !(c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U'));
}

// Helper function to count words with exactly n consonants
function CountWordsWithConsonants(s: string, n: int): int
    reads {}
{
    var count := 0;
    var currentWord := "";
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length // i is within bounds
        invariant count == CountWordsWithCurrentWord(s[0..i], n, currentWord) // Count of words with exactly n consonants found so far
    {
        if s[i] == ' ' {
            if currentWord.Length > 0 && CountConsonants(currentWord) == n {
                count := count + 1;
            }
            currentWord := ""; // Reset current word
        } else {
            currentWord := currentWord + s[i]; // Build the current word
        }
        i := i + 1;
    }
    // Check the last word
    if currentWord.Length > 0 && CountConsonants(currentWord) == n {
        count := count + 1;
    }
    return count;
